riables utilisées dans :; l-c64-string.asm;------------------------------------------------------------------------------len               .byte 0  ;cx                .byte 0  ;cy                .byte 0  ;bcol              .byte 0  ;;------------------------------------------------------------------------------; Variables utilisées dans :; l-cbm-disk.asm, l-c64-vicii.asm,  l-cbm-mem.asm;------------------------------------------------------------------------------loops             .byte 0  ;loop16            .word 0  ;scrncar           .fill 1024,0   ; Zone de sauvegarde de la RAM ecran.scrncol           .fill 1024,0   ; Zone de sauvegarde de la RAM couleur.;------------------------------------------------------------------------------; Variables pour l-cbm-disk.asm;------------------------------------------------------------------------------dsk_data_s        .word $0000 ; Pointeur sur le début des données.dsk_data_e        .word $2000 ; Pointeur sur la fin des données. dsk_dev           .byte $08   ; No. de périphérique.dsk_lfsno         .byte $00   ; No. de fichier logique.dsk_fnptr         .word $00   ; Pointeur vers le nom du fichier.dsk_fnlen         .byte 0     ; Nombre de caractère dans le nom de fichier.;------------------------------------------------------------------------------; Variables  pour fichier l-c64-drawbox.asm.; Variables globales des paramètres de dessin de fenetre texte.;------------------------------------------------------------------------------db_left           .byte 0     ; Caractère Gauche de la ligne courante. db_right          .byte 0     ; Caractère droit de la ligne courante.db_mid            .byte 0     ; Caractère central de la ligne courante.drawbox_top       .byte 0     ; Coordonné du haut de la boite.drawbox_left      .byte 0     ; Coordonné de la gauche de la boîte.drawbox_width     .byte 0     ; Largeur de la boîte.drawbox_height    .byte 0     ; Hauteur de la boîte.drawbox_colour    .byte 0     ; Couleur de la boîte.drawbox_curline   .byte 0        ; No de la ligne courante à dessiner.drawbox_bascol    .byte 0        ; Case de mémorisation de la couleur Basic.   offset            .byte 0;------------------------------------------------------------------------------genbyte1          .byte 0  ; genword1          .word 0  ; ;------------------------------------------------------------------------------